22:class DetektKotlinCompilerPlugin : KotlinCompilerPluginSupportPlugin {
23:
24:    override fun apply(target: Project) {
25:        target.pluginManager.apply(DetektBasePlugin::class.java)
26:
27:        val extension = target.extensions.getByType(DetektExtension::class.java)
28:
29:        target.tasks.withType(KotlinJvmCompile::class.java).configureEach { task ->
30:            task.extensions.create(DETEKT_EXTENSION, KotlinCompileTaskDetektExtension::class.java, target).apply {
31:                isEnabled.convention(extension.enableCompilerPlugin)
32:                baseline.convention(extension.baseline)
33:                debug.convention(extension.debug)
34:                buildUponDefaultConfig.convention(extension.buildUponDefaultConfig)
35:                allRules.convention(extension.allRules)
36:                disableDefaultRuleSets.convention(extension.disableDefaultRuleSets)
37:                parallel.convention(extension.parallel)
38:                config.from(extension.config)
39:                excludes.convention(DetektPlugin.defaultExcludes)
40:            }
41:        }
42:    }
43:
44:    override fun applyToCompilation(kotlinCompilation: KotlinCompilation<*>): Provider<List<SubpluginOption>> {
45:        val project = kotlinCompilation.target.project
46:
47:        val projectExtension = project.extensions.getByType(DetektExtension::class.java)
48:
49:        val taskExtension = kotlinCompilation.compileTaskProvider.map {
50:            it.extensions.getByType(KotlinCompileTaskDetektExtension::class.java)
51:        }
52:
53:        project.configurations.getByName("kotlinCompilerPluginClasspath")
54:            .extendsFrom(project.configurations.getAt(CONFIGURATION_DETEKT_PLUGINS))
55:
56:        val options = project.objects.listProperty(SubpluginOption::class.java).apply {
57:            add(SubpluginOption("debug", taskExtension.get().debug.toString()))
58:            add(SubpluginOption("configDigest", taskExtension.get().config.toDigest()))
59:            add(SubpluginOption("isEnabled", taskExtension.get().isEnabled.getOrElse(false).toString()))
60:            add(SubpluginOption("useDefaultConfig", taskExtension.get().buildUponDefaultConfig.get().toString()))
61:            add(SubpluginOption("allRules", taskExtension.get().allRules.get().toString()))
62:            add(SubpluginOption("disableDefaultRuleSets", taskExtension.get().disableDefaultRuleSets.get().toString()))
63:            add(SubpluginOption("parallel", taskExtension.get().parallel.get().toString()))
64:            add(SubpluginOption("rootDir", project.rootDir.toString()))
65:            add(SubpluginOption("excludes", taskExtension.get().excludes.get().encodeToBase64()))
66:
67:            taskExtension.get().reports.all { report ->
68:                report.enabled.convention(true)
69:                report.destination.convention(
70:                    projectExtension.reportsDir.file("${kotlinCompilation.name}.${report.name}")
71:                )
72:
73:                if (report.enabled.get()) {
74:                    add(
75:                        SubpluginOption(
76:                            "report",
77:                            "${report.name}:${report.destination.asFile.get().absolutePath}"
78:                        )
79:                    )
80:                }
81:            }
82:        }
83:
84:        taskExtension.get().baseline.getOrNull()?.let { options.add(SubpluginOption("baseline", it.toString())) }
85:        taskExtension.get().config.forEach {
86:            options.add(SubpluginOption("config", it.absolutePath))
87:        }
88:
89:        return options
90:    }
91:
92:    override fun getCompilerPluginId(): String = "detekt-compiler-plugin"
93:
94:    override fun getPluginArtifact(): SubpluginArtifact =
95:        SubpluginArtifact("dev.detekt", "detekt-compiler-plugin", BuildConfig.DETEKT_COMPILER_PLUGIN_VERSION)
96:
97:    override fun isApplicable(kotlinCompilation: KotlinCompilation<*>): Boolean =
98:        kotlinCompilation.platformType in setOf(KotlinPlatformType.jvm, KotlinPlatformType.androidJvm)
99:}
