101:internal fun ConfigurableFileCollection.toDigest(): String {
102:    val concatenatedConfig = this
103:        .filter { it.isFile }
104:        .map(File::readBytes)
105:        .fold(byteArrayOf()) { acc, file -> acc + file }
106:
107:    return Base64.getEncoder().encodeToString(
108:        MessageDigest.getInstance("SHA-256").digest(concatenatedConfig)
109:    )
110:}
111:
112:private fun Set<String>.encodeToBase64(): String {
113:    val os = ByteArrayOutputStream()
114:
115:    ObjectOutputStream(os).use { oos ->
116:        oos.writeInt(size)
117:        forEach(oos::writeUTF)
118:        oos.flush()
119:    }
120:
121:    return Base64.getEncoder().encodeToString(os.toByteArray())
122:}
