25:    val configuration = monitor.measure(Phase.LoadConfig) {
26:        workaroundConfiguration(loadConfiguration())
27:    }
28:    val settings = monitor.measure(Phase.CreateSettings) {
29:        ProcessingSettings(this, configuration, monitor).apply {
