16:private val supportedLanguageVersions = LanguageVersion.entries
17:    .filterNot(LanguageVersion::isUnsupported)
18:    .joinToString { it.toString() }
19:class ApiVersionConverter : IStringConverter<ApiVersion> {
20:    override fun convert(value: String): ApiVersion {
21:        val languageVersion = LanguageVersion.fromFullVersionString(value)
22:        require(languageVersion != null && !languageVersion.isUnsupported) {
23:            "\"$value\" passed to --api-version, expected one of [$supportedLanguageVersions]"
24:        }
25:        return ApiVersion.createByLanguageVersion(languageVersion)
26:    }
27:}
