29:class LanguageVersionConverter : IStringConverter<LanguageVersion> {
30:    override fun convert(value: String): LanguageVersion {
31:        val languageVersion = LanguageVersion.fromFullVersionString(value)
32:        require(languageVersion != null && !languageVersion.isUnsupported) {
33:            "\"$value\" passed to --language-version, expected one of [$supportedLanguageVersions]"
34:        }
35:        return languageVersion
36:    }
37:}
