39:class JvmTargetConverter : IStringConverter<JvmTarget> {
40:    override fun convert(value: String): JvmTarget =
41:        checkNotNull(JvmTarget.fromString(value)) {
42:            val validValues = JvmTarget.entries.joinToString { it.toString() }
43:            "Invalid value passed to --jvm-target, expected one of [$validValues]"
44:        }
45:}
