47:class ClasspathResourceConverter : IStringConverter<URL> {
48:    override fun convert(resource: String): URL {
49:        val relativeResource = if (resource.startsWith("/")) resource else "/$resource"
50:        return javaClass.getResource(relativeResource)
51:            ?: throw ParameterException("Classpath resource '$resource' does not exist!")
52:    }
53:}
