59:class ReportPathConverter : IStringConverter<ReportPath> {
60:    override fun convert(value: String): ReportPath =
61:        try {
62:            ReportPath.from(value)
63:        } catch (e: IllegalArgumentException) {
64:            throw ParameterException(e.message, e)
65:        }
66:}
