72:class PathValidator : IValueValidator<List<Path>> {
73:    override fun validate(name: String, value: List<Path>) {
74:        value.forEach {
75:            if (!it.exists()) throw ParameterException("Path '$it' passed to $name does not exist.")
76:        }
77:    }
78:}
