80:class DirectoryValidator : IValueValidator<Path> {
81:    override fun validate(name: String, value: Path) {
82:        if (!value.isDirectory()) throw ParameterException("Value passed to $name must be a directory.")
83:    }
84:}
85:
86:class FilterSplitter : IParameterSplitter {
87:    override fun split(value: String): List<String> = value.split(',', ';')
88:}
89:
90:class FilterValidator : IValueValidator<List<String>> {
91:    override fun validate(name: String, value: List<String>) {
92:        if (value.any { it.isBlank() }) {
93:            throw ParameterException("Value passed to $name contains empty globs.")
94:        }
95:        if (value.any { it.trim() != it }) {
96:            throw ParameterException("Value passed to $name contains globs that start or end with space.")
97:        }
98:    }
